// Permanent COP editorial asset: La Californie, Cannes, September 2026.
// The JPEG is embedded so the public response stays immutable and CDN-cacheable.
const IMAGE_BASE64 = '';

export default function handler(req, res) {
  res.setHeader('Content-Type', 'image/jpeg');
  res.setHeader('Cache-Control', 'public, max-age=31536000, immutable');
  res.status(200).send(Buffer.from(IMAGE_BASE64, 'base64'));
}
